{%- set columns = dbt_utils.get_column_values(ref('stg_airports__malaysia_distances'), 'b_name') | list | sort -%}

with dist as (

    select * from {{ ref('stg_airports__malaysia_distances') }}

),

pivoted as (

    select
        a_name,
        {%- for column in columns %}
        max(case when b_name = '{{ column }}' then distance_km end) as "{{ column }}"
        {%- if not loop.last -%}
        ,
        {%- endif %}
        {%- endfor %}
    from
        dist
    group by a_name

)

select
    a_name,
    {%- for column in columns %}
    coalesce("{{ column }}", 0) as "{{ column }}"
    {%- if not loop.last -%}
    ,
    {%- endif %}
    {%- endfor %}
from pivoted
order by a_name
